import styled from "styled-components";

export const RegisterWrapper = styled.main`
    width: 100%;
    height: 100vh;

    position: relative;

    display: flex;
    align-items: center;
    justify-content: center;

` 
export const BodyRegisterContainer= styled.div`
    width: 100vw;
    height: 100vh;
    display: flex;
    flex-direction: column;
    position:relative;
   
`

export const CardRegisterContainer = styled.div`
    width:25%;
    height:40%;
    top:0;
    left:0;
    transform: translate(-50%, -50%);
    position: absolute;
    box-shadow: 5px 4px 6px rgba(0,0,0,0.25);

`
